=== shm.hpp ===
// Shared-mmap allocation for andesim.
//
// The caller asks for `size` bytes; we resolve a backing directory over a
// tier list (first fit wins, fit = size + 256 MiB free), allocate a sparse
// file with mkstemp+truncate, and print one status line that always names
// the chosen tier -- and, when we fell past /dev/shm, why. HSIM_MMAP_DIR
// pins a single tier (hard error if it does not fit; no fallback past it).
#ifndef ANDESIM_SHM_HPP
#define ANDESIM_SHM_HPP

#include <cstdint>
#include <functional>
#include <string>
#include <vector>

namespace andes_sim {

// Free-space headroom a tier must have beyond the requested size.
inline constexpr long long kMmapSafetyMargin = 256LL * 1024 * 1024;

// One backing-store candidate: the directory plus the label used in
// status/error messages ("/dev/shm", "~/.cache/andesim", "HSIM_MMAP_DIR=..").
struct MmapTier {
  std::string dir;
  std::string label;
};

// resolve_mmap_dir result: the chosen dir ("" on failure) and, when a tier
// was skipped, a human note saying which and why ("" when tiers[0] fit).
struct MmapDirChoice {
  std::string dir;
  std::string note;
};

// Parse "8G" / "512M" / "1024" / "1.5G" into a positive byte count. On success
// returns the count and leaves `err` empty; on failure returns 0 and sets `err`
// to the argparse-style message. Fractional values truncate (1.5G -> whole
// bytes).
long long parse_size(const std::string& spec, std::string& err);

// L26/F2: the physical shared mmap is one V-scratch page (HYBRID_V_SCRATCH_BYTES)
// larger than the program's --mem-size, so the V-register transport page sits
// just ABOVE the program's declared RAM. No program layout -- low stack, top-of-
// RAM stack, or a heap grown to the ceiling -- can reach a page past its own
// RAM, so the scratch can never be clobbered. The vsim side parks the scratch
// at the mmap's top page (v_scratch_gpa), which equals ram_base + program_bytes.
long long physical_mmap_bytes(long long program_bytes);

// The largest --mem-size whose physical mmap still fits the 2 GiB AE350 DRAM
// window (program_bytes + scratch page <= 2 GiB). --mem-size is capped here.
long long max_program_mem_bytes();

// U10b/U10e: ceiling check for `--mode fast --runtime linux`. With ram_base
// support the guest addresses the contiguous high view -- DRAM alias (2 GiB)
// + DRAM_EXT (14 GiB) from 0x8_00000000 -- so the ceiling is 16 GiB (QEMU
// AE350 refuses more anyway, but failing here beats staging first). Returns
// "" when `spec` is empty (the 1G default applies later), malformed
// (qemu_m_args owns that error), or within the window; otherwise a
// ready-to-print message. Hybrid mode keeps its own separate 2 GiB cap.
std::string fast_linux_mem_error(const std::string& spec);
=== memmap.hpp ===
// The hybrid guest memory map: which regions a workload may touch in
// `run --mode hybrid`, composed from the same sources the run itself trusts.
//
// Only hybrid-SUPPORTED regions appear (PM rule): regions modeled by BOTH
// engines whose content or device behavior the handoff actually provides.
// QEMU-only devices (MROM/PLIC/PLMT/virtio/...), vsim-reserved holes (PLDM),
// and unverified-parity devices (UART1/SMU) are deliberately absent.
//
// Sources, in provenance order:
//   - DRAM + V-scratch: the driver's own window math (--mem-size; the
//     reserved HYBRID_V_SCRATCH_BYTES page above program RAM, L26).
//   - ILM/DLM/HVM bases: the engine's `--print-qemu-config` text -- the same
//     staged qemu.cfg the QEMU fast leg boots with, so the printed bases are
//     exactly the run's effective geometry.
//   - ILM/DLM/HVM sizes + row presence: the engine descriptor's backdoor-gated
//     ilm/dlm/hvm_size (0 = content cannot cross the handoff -> row omitted).
//   - SimControl/HTIF + UART2: fixed AE350 platform constants, identical in
//     QEMU (hw/riscv/andes_ae350.c memmap table) and vsim (platform
//     memory_map.h); drift is guarded by tests/andes_sim/
//     test_andes_sim_print_memmap.sh, which cross-checks the engine's own
//     `--print-memmap` dump.
//   - L2C register window (0xe0500000): intentionally absent until an engine
//     ships with an L2C -- `--describe` carries no L2C capability today, and
//     every current engine is built _NDS_L2C_CACHE_SIZE_KB=0.
#ifndef ANDESIM_MEMMAP_HPP
#define ANDESIM_MEMMAP_HPP

#include <cstdint>
#include <map>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"

namespace andes_sim {

struct MemmapRow {
  std::string region;     // "DRAM", "V-scratch", "ILM", ...
  uint64_t base = 0;      // guest physical, first byte
  uint64_t end = 0;       // guest physical, LAST byte (inclusive)
  std::string transport;  // what the handoff does with the region's content
};

struct MemmapResult {
  std::vector<MemmapRow> rows;
  std::vector<std::string> warnings;  // e.g. LM geometry unavailable
};

// Extract the `riscv.andes.ae350.soc` [global] properties from an engine's
// --print-qemu-config text: property name -> value string, other drivers'
// globals (the CPU ISA block) excluded.
std::map<std::string, std::string> qemu_cfg_soc_props(
    const std::string& cfg_text);

// Compose the hybrid map for `eng` with `mem_size` bytes of program RAM
// (--mem-size) and the engine's --print-qemu-config text (may be empty:
// LM/HVM rows are then dropped with a warning naming the missing probe).
MemmapResult hybrid_memmap(const EngineDescriptor& eng, long long mem_size,
                           const std::string& qemu_cfg_text);

// "128M" / "4K" / "2G" for whole binary multiples, plain decimal bytes else.
std::string fmt_size(uint64_t bytes);

// Render as an aligned text table (REGION/BASE/END/SIZE/TRANSPORT), warnings
// appended one per line.
std::string render_memmap(const MemmapResult& r);

}  // namespace andes_sim

#endif  // ANDESIM_MEMMAP_HPP

