/*
 * multi_arch_toplevel.cpp
 *
 * Multi-Architecture Simulation Toplevel for Andes FastSim
 * Dynamic Loading Version
 */

#include <systemc>
#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <cci_configuration>

#include <scp/report.h>
#include <luafile_tool.h>
#include <cciutils.h>
#include <module_factory_container.h>

// Include QemuInstance to register it statically
#include "qemu-instance.h"

using namespace sc_core;

class MultiArchPlatform : public gs::ModuleFactory::Container {
  protected:
      cci::cci_param<int> m_quantum_ns;

  public:
      MultiArchPlatform(const sc_core::sc_module_name& n)
          : gs::ModuleFactory::Container(n)
          , m_quantum_ns("quantum_ns", 1000000, "TLM-2.0 global quantum in ns")
      {
          using tlm_utils::tlm_quantumkeeper;

          sc_core::sc_time global_quantum(m_quantum_ns, sc_core::SC_NS);
          tlm_quantumkeeper::set_global_quantum(global_quantum);
      };
};

int sc_main(int argc, char* argv[]) {
    // 0. Initialize Logging
    scp::init_logging(scp::log::WARNING);

    // 1. Initialize CCI Parameters
    cci::cci_originator orig("sc_main");
    cci::cci_broker_handle broker = cci::cci_get_global_broker(orig);

    const char* lua_file = "conf/multi_arch_platform.lua";
    for (int i = 1; i < argc; i++) {
        if (std::string(argv[i]) == "--gs_luafile" && i + 1 < argc) {
            lua_file = argv[++i];
        }
    }

    gs::LuaFile_Tool luareader;
    if (luareader.config(broker, lua_file)) {
        SCP_FATAL("sc_main") << "Failed to load lua config file: " << lua_file;
    }

    // 2. Instantiate Platform (Automatic construction and binding)
    MultiArchPlatform platform("platform");

    sc_start();

    /*
     * Carry a guest-reported failure out to the exit status, so a run that ends
     * because the guest's checks failed is distinguishable both from one that
     * finished cleanly and from one that was killed for running too long.
     * StopperV2 sets its "failed" parameter when it sees its failure value.
     */
    for (auto handle : broker.get_param_handles()) {
        const std::string name = handle.name();
        if (name.size() >= 7 && name.compare(name.size() - 7, 7, ".failed") == 0) {
            if (handle.get_cci_value().to_json() == "true") {
                SCP_WARN("sc_main") << name << " is set; exiting non-zero.";
                return 1;
            }
        }
        /*
         * A guest that ended the run through semihosting SYS_EXIT (a libc
         * image returning from main) reports its status on the instance;
         * carry a non-zero one out as the process exit status.
         */
        if (name.size() >= 18 && name.compare(name.size() - 18, 18, ".guest_exit_status") == 0) {
            const std::string v = handle.get_cci_value().to_json();
            const int status = std::atoi(v.c_str());
            if (status > 0) {
                SCP_WARN("sc_main") << name << " = " << status << "; exiting non-zero.";
                return status & 0xff;

